// Package layout holds Go views of the C structures YANET keeps in shared
// memory, generated by shmgen from the DWARF of the dataplane binary.
//
// The views apply only to the architecture of the binary they were
// generated from; a build for another one has none until they are
// generated from a binary of that architecture.
package layout

//go:generate go run ../cmd/shmgen -binary ../../../build/dataplane/yanet-dataplane -package layout -import github.com/yanet-platform/yanet2/controlplane/native/layout -out layout.go -test layout_test.go dp_config cp_config cp_config_gen agent cp_module dp_worker
